  "help.realized_volatility.concept": { zh: "已实现波动率：由历史收益率年化计算的价格波动程度，越高代表价格摆动越剧烈。", en: "Realized volatility: annualized price fluctuation computed from historical returns; higher means larger price swings." },
  "help.atr.concept": { zh: "ATR（平均真实波幅）：衡量单位周期内的平均波动幅度，用于判断网格步长是否与行情匹配。", en: "ATR (Average True Range): the average movement per period, used to gauge whether the grid step matches market volatility." },
  "help.max_drawdown.concept": { zh: "最大回撤：区间内从最高点到随后最低点的最大跌幅，衡量下行风险。", en: "Max drawdown: the largest peak-to-trough decline over the window, a measure of downside risk." },
  "help.range_pct.concept": { zh: "区间幅度：分析窗内最高价与最低价之间的百分比跨度。", en: "Range %: the percentage span between the highest and lowest price over the window." },
  "help.trend.concept": { zh: "趋势：分析窗内价格相对起点的涨跌幅，正为上行、负为下行。", en: "Trend: price change relative to the start of the window — positive is up, negative is down." },
  "help.vpvr_node.concept": { zh: "VPVR 高量价位：成交量按价格分布中的高成交密集区，常作为支撑/阻力参考。", en: "VPVR high-volume node: a price level with concentrated traded volume, often acting as support/resistance." },
  "help.confidence.concept": { zh: "置信度：模型对该推荐的主观把握程度（0–100%），非历史回测胜率。", en: "Confidence: the model's subjective conviction in a recommendation (0–100%), not a backtested win rate." },

