  "referral.rebate_pnl_hint": { zh: "如使用邀请码注册该交易所，可获得其中约 ${rebate} 的手续费返还。", en: "Register on this exchange with an invite code to get about ${rebate} of these fees back." },
  "referral.milestone": { zh: "这个机器人已付 ${fees} 手续费，如使用邀请码注册该交易所，可获得其中约 ${rebate} 的手续费返还。", en: "This bot has now paid ${fees} in fees — register on this exchange with an invite code to get about ${rebate} of it back." },
  "learn.fees.nav": { zh: "费用与返佣", en: "Fees & Rebates" },
  "learn.fees.title": { zh: "手续费与资金费完全指南", en: "Complete Guide to Fees & Funding" },
  "learn.fees.page_intro": { zh: "看懂这两笔成本，是网格交易长期盈利的前提。", en: "Understanding these two costs is the foundation of long-term grid profitability." },
  "learn.fees.hero_title": { zh: "别让手续费，悄悄吃掉你的本金", en: "Don't let fees quietly eat your principal" },
  "learn.fees.hero_title_accent": { zh: "悄悄吃掉你的本金", en: "quietly eat your principal" },
  "learn.fees.hero_sub": { zh: "在杠杆与高频网格下，手续费会被放大到惊人——但其中很大一部分，本可以拿回来。", en: "Under leverage and high-frequency grids, fees balloon to staggering levels — but a big share of them can come back to you." },
