  "learn.fees.why_title": { zh: "为什么手续费这么可怕", en: "Why fees get so brutal" },
  "learn.fees.calc1": { zh: "本金 1,000 · 20× 杠杆 → 名义仓位 20,000", en: "Principal 1,000 · 20× leverage → 20,000 notional position" },
  "learn.fees.calc2": { zh: "一次开仓手续费 ≈ 10u，平仓 ≈ 10u → 一次开平仓 20u，已是本金的 2%", en: "Opening ≈ 10u, closing ≈ 10u → one open-close round costs 20u, already 2% of principal" },
  "learn.fees.calc3": { zh: "一天开平仓 50 次 → 无声无息间，手续费已等于你的全部本金。", en: "50 open-close rounds a day → quietly, fees already equal your entire principal." },
  "learn.fees.save_tagline": { zh: "你的手续费，本应有一部分属于你。", en: "A share of your fees was always meant to be yours." },
  "learn.fees.bar_principal": { zh: "你的本金", en: "Your principal" },
