  // ── 策略文档页（设计稿 pageDocs 还原）──
  "docs.nav": { zh: "策略文档", en: "Strategy Docs" },
  "docs.title": { zh: "策略文档", en: "Strategy Documentation" },
  "docs.subtitle": { zh: "GridPilot 的核心是动态网格 —— 在预设价格区间内低买高卖，叠加追踪建仓、三区间动态定价与分层止损缓冲，把震荡行情转化为持续现金流，并量化为 Alpha。", en: "GridPilot's core is the dynamic grid — buying low and selling high within a preset range, layered with trailing entry, three-zone dynamic pricing and tiered stop-loss buffers, turning ranging markets into steady cash flow quantified as Alpha." },
  "docs.lifecycle_label": { zh: "策略生命周期", en: "Strategy Lifecycle" },
  "docs.life_entry_title": { zh: "追踪建仓", en: "Trailing Entry" },
  "docs.life_entry_desc": { zh: "等待回调企稳，确认低点反弹后才建仓，避免顶部接盘", en: "Wait for a pullback to stabilize and confirm a rebound before entering, avoiding buying the top" },
  "docs.life_grid_title": { zh: "网格运行", en: "Grid Running" },
  "docs.life_grid_desc": { zh: "在区间内逐格低买高卖，POC 挂单循环累积利润", en: "Buy low, sell high grid by grid; POC orders cycle to accumulate profit" },
  "docs.life_tp_title": { zh: "止盈平仓", en: "Take Profit" },
  "docs.life_tp_desc": { zh: "触及止盈线或满仓后收尾，结算已实现盈亏与 Alpha", en: "Wind down at the take-profit line or full position; settle realized P&L and Alpha" },
  "docs.zones_label": { zh: "三区间动态定价", en: "Three-Zone Dynamic Pricing" },
  "docs.zone_main": { zh: "主网格区", en: "Main Grid" },
  "docs.zone_iso": { zh: "隔离带", en: "Buffer" },
  "docs.zone_sl": { zh: "止损缓冲区", en: "Stop-Loss Zone" },
  "docs.zone_main_title": { zh: "主网格区 · POC Maker", en: "Main Grid · POC Maker" },
  "docs.zone_main_desc": { zh: "核心交易区。所有网格挂单走 Post-Only，只做 Maker，逐格低买高卖累积利润。", en: "The core trading zone. All grid orders are Post-Only, Maker-only, buying low and selling high grid by grid." },
  "docs.zone_iso_title": { zh: "隔离带", en: "Buffer Zone" },
  "docs.zone_iso_desc": { zh: "主网格与止损区之间的缓冲，避免价格在边界反复触发误操作。", en: "A buffer between the main grid and stop-loss zone, preventing repeated mis-triggers at the boundary." },
  "docs.zone_sl_title": { zh: "止损缓冲区 · 分层减仓", en: "Stop-Loss Zone · Tiered Reduction" },
  "docs.zone_sl_desc": { zh: "价格跌破止损起点后，分多层逐步减仓而非一次性砍仓，平滑滑点、保留反弹机会。", en: "Below the stop-loss start, position is reduced in tiers rather than all at once, smoothing slippage and keeping rebound upside." },
  "docs.mech_label": { zh: "核心机制", en: "Core Mechanisms" },
  "docs.mech_boxes_title": { zh: "多段箱体", en: "Multi-segment Boxes" },
  "docs.mech_boxes_desc": { zh: "一个机器人可配置多段价格区间（箱体），分批承接不同价位，扩大覆盖、分散风险。", en: "One robot can hold multiple price ranges (boxes), absorbing different levels in batches to widen coverage and spread risk." },
  "docs.mech_entry_title": { zh: "追踪建仓", en: "Trailing Entry" },
  "docs.mech_entry_desc": { zh: "挂单前先用追踪回调判定低点，确认反弹幅度达阈值才下首单，降低建仓成本。", en: "Before placing orders, a trailing pullback identifies the low; the first order fires only after the rebound passes a threshold, lowering entry cost." },
  "docs.mech_dynamic_title": { zh: "实时动态委托", en: "Real-time Dynamic Orders" },
  "docs.mech_dynamic_desc": { zh: "随标记价移动持续改单，保证挂单始终贴合网格目标价，减少漏单与偏移。", en: "Orders are continuously amended as the mark price moves, keeping them aligned with grid target prices and reducing misses and drift." },
  "docs.mech_sl_title": { zh: "分层止损缓冲", en: "Layered Stop-Loss" },
  "docs.mech_sl_desc": { zh: "止损区按层级挂算法单，逐步减仓并保留紧急全平兜底，控制极端行情回撤。", en: "The stop-loss zone places algo orders by tier, reducing gradually with an emergency full-close fallback to control drawdowns in extreme moves." },
  "docs.alpha_label": { zh: "什么是 Alpha", en: "What is Alpha" },
  "docs.alpha_intro": { zh: "Alpha 是 GridPilot 相对「朴素网格」的超额收益，由两部分构成：", en: "Alpha is GridPilot's excess return over a naive grid, made of two parts:" },
  "docs.alpha_maker_term": { zh: "Maker 节省", en: "Maker Savings" },
  "docs.alpha_maker_desc": { zh: "POC 挂单省下的吃单费", en: "taker fees saved by POC orders" },
  "docs.alpha_gtc_term": { zh: "GTC 超额", en: "GTC Excess" },
  "docs.alpha_gtc_desc": { zh: "突破行情主动捕获的额外利润", en: "extra profit captured in breakouts" },
  "docs.alpha_formula": { zh: "Alpha = Maker 节省 + GTC 超额", en: "Alpha = Maker Savings + GTC Excess" },
  "docs.glossary_label": { zh: "术语表", en: "Glossary" },
  "docs.glossary_poc_term": { zh: "POC（Post-Only）", en: "POC (Post-Only)" },
  "docs.glossary_poc_desc": { zh: "只挂不吃的 Maker 单，不成交则撤单重挂。", en: "Maker-only orders that never take; re-posted if unfilled." },
  "docs.glossary_gtc_term": { zh: "GTC（Good-Till-Cancel）", en: "GTC (Good-Till-Cancel)" },
  "docs.glossary_gtc_desc": { zh: "长期有效单，用于突破行情主动吃单。", en: "Long-lived orders used to actively take in breakouts." },
  "docs.glossary_avg_term": { zh: "网格均价", en: "Grid Average Price" },
  "docs.glossary_avg_desc": { zh: "某格对应的理论目标价，用于核算节省。", en: "The theoretical target price per grid, used to compute savings." },
  "docs.glossary_full_term": { zh: "满仓线", en: "Full-Position Line" },
  "docs.glossary_full_desc": { zh: "所有网格买单成交后的最大持仓价位。", en: "The max position price after all grid buys fill." },
  "docs.risk_label": { zh: "风险提示", en: "Risk Warning" },
  "docs.risk_body": { zh: "合约交易具高杠杆风险。网格策略适合震荡行情，单边下跌可能触发止损或亏损。请理性配置仓位与杠杆，仅投入可承受损失的资金。", en: "Futures trading carries high leverage risk. Grid strategies suit ranging markets; a one-way drop may trigger stop-loss or losses. Size positions and leverage prudently, and only invest what you can afford to lose." },

