    "help.fee.concept": "交易所對每筆成交收取的費用；分掛單(Maker)與吃單(Taker)兩檔費率。",
    "help.fee.note": "手續費由交易所收取，GridPilot 一分不抽。同一筆交易，掛單(Maker)約 0.02%、吃單(Taker)約 0.05%（以交易所為準）——我們預設替你掛單，每筆約省 0.03%；只有當機會稍縱即逝、錯過更可惜時才主動吃單。所以這裡顯示的，已是為你最佳化過的結果。",
    "help.fee.cta": "了解費用與返佣",
    "help.savings.concept": "這一筆相對「交易所原生網格掛單價（平均網格價）」多賺到的價差——我們主動追價拿到更優成交，原生網格做不到。",
    "help.avg_grid_price.concept": "這就是交易所原生網格機器人在這一格會掛出的賣出價／買入價。我們每一筆實際成交都比它更優——賣得更高、買得更低，差額就是超額利潤（Alpha）。",
    "help.fill_price.concept": "這一筆訂單實際成交的價格（交易所撮合價）。",
    "help.order_price.concept": "我們最初掛出這筆訂單時的委託價；與成交價的差異反映追價／滑點。",
    "help.savings.note": "不是憑空多收，而是「追逐下單」爭取到更優成交價帶來的真實收益，已包含在已實現盈虧裡；累計起來就是 Alpha 超額利潤。",
    "help.alpha.concept": "交易所原生網格只在固定格價掛單被動等成交；GridPilot 主動追逐更優成交價、並在價格大幅跳動時鎖定價差，多賺出的這部分就是 Alpha 超額利潤。",
    "help.alpha.note": "這是 GridPilot 獨有的執行能力，交易所自帶網格賺不到。它已計入「已實現盈虧」，不會額外疊加到總盈虧之外。",
    "help.maker_taker.concept": "掛單(Maker, POC)=掛限價被動等成交，費率低(≈0.02%)；吃單(Taker, GTC)=主動成交，即時但費率高(≈0.05%)。",
    "help.maker_taker.note": "預設替你掛單省費（每筆約省 0.03%）；只有當價格快速跑開、再等就會錯過時，才主動吃單抓住價差。",
    "help.isolation.concept": "主網格滿倉線與止損區起點之間的緩衝距離。",
    "help.isolation.note": "避免主網格剛滿就觸發止損。",
    "help.trailing_entry.concept": "不立即開網格，先盯價格極值、等回調一定比例再建倉，爭取更優入場點。",
    "help.take_profit.concept": "網格的獲利目標價；價格到此、倉位清空即止盈離場。",
    "help.main_grid.concept": "核心交易區——「格數×步長」決定覆蓋的價格範圍與每格間距。",
    "help.portion_size.concept": "每個網格掛單的基礎數量（單位＝交易對基礎幣，如 ETH）。",
    "help.leverage.concept": "合約槓桿倍數；放大倉位與盈虧，也放大風險。",
    "help.stop_loss.concept": "價格跌穿滿倉線後的清算保護——「格數×步長」決定止損區的深度與節奏。",
    "help.stop_loss.note": "最低箱可設 0 格＝無止損。",
    "help.activation.concept": "價格進入此點才激活該箱開始交易；留空則自動取主網格中值。",
    "help.mark_price.concept": "交易所用於計算未實現盈虧與清算的參考價（不是最新成交價）。",
    "help.position.concept": "當前持有的合約數量、方向（多/空）與持倉均價。",
    "help.realized_pnl.concept": "已平倉部分鎖定的盈虧（含手續費）。只統計已成交平倉的部分，不隨當前價格即時跳動。",
    "help.realized_pnl.note": "跨該機器人/箱體所有歷史會話累計。",
    "help.unrealized_pnl.concept": "當前持倉按標記價計算的浮動盈虧，平倉前會隨價格波動。",
    "help.total_pnl.concept": "已實現＋未實現浮盈，當前的整體盈虧；其中未實現部分會隨行情即時變動。",
    "help.total_pnl.note": "超額利潤已含在已實現裡，不另加。",
    "help.reorders.concept": "為保持掛單競爭力（追價）而撤單重掛的次數。",
    "help.reorders.note": "本次會話統計。",
    "help.net_pnl.concept": "淨盈虧 = 已實現 − 手續費 − 資金費",
    "help.robot_total_pnl.concept": "機器人總損益 = 該機器人所有箱體淨損益 + 當前持倉未實現",
    "referral.title": "降低手續費：註冊時填返佣",
    "referral.subtitle": "在槓桿與高頻網格下，手續費會被悄悄放大，日積月累並不小。註冊時填一個返佣碼，就能把已付手續費長期返還約 20%——相當於給每筆交易再打個折。",
