    "help.fee.concept": "取引所が各約定に対して請求する手数料。メイカー（Maker）とテイカー（Taker）の2段階の費率があります。",
    "help.fee.note": "手数料は取引所が請求するもので、GridPilot は一切受け取りません。同じ取引でも、メイカー(Maker)は約0.02%、テイカー(Taker)は約0.05%（取引所による）——私たちはできる限りメイカーで約定し、1取引あたり約0.03%を節約します。テイカーを使うのは、見逃すと惜しい一瞬の好機のときだけ。ここに表示されているのは、すでにあなたのために最適化された結果です。",
    "help.fee.cta": "手数料とリベート",
    "help.savings.concept": "この約定で、取引所のネイティブグリッド注文価格（平均グリッド価格）に対して獲得した追加の値幅——主体的に価格を追いかけてより良い約定を得るもので、ネイティブグリッドにはできません。",
    "help.avg_grid_price.concept": "これは取引所のネイティブグリッドボットがこのグリッドラインで出すであろう売値／買値そのものです。私たちの実際の約定はすべてそれを上回ります——より高く売り、より安く買う——その差が超過利益（Alpha）です。",
    "help.fill_price.concept": "この注文が実際に約定した価格（取引所のマッチング価格）。",
    "help.order_price.concept": "この注文を最初に発注したときの注文価格；約定価格との差は追いかけ／スリッページを反映します。",
    "help.savings.note": "余分に請求されるものではなく、「チェイス注文」でより有利な約定価格を勝ち取った実際の利益であり、既に実現損益に含まれています。累計すると Alpha 超過利益になります。",
    "help.alpha.concept": "取引所標準のグリッドは固定価格に注文を置いて受動的に約定を待つだけ。GridPilot はより有利な約定価格を能動的に追い、価格が大きく動いた時に値幅を確定します。こうして多く稼いだ分が Alpha 超過利益です。",
    "help.alpha.note": "これは GridPilot 独自の執行能力で、取引所標準のグリッドでは得られません。既に「実現損益」に計上されており、総損益に上乗せされるものではありません。",
    "help.maker_taker.concept": "メイカー(Maker, POC)=パッシブな指値注文で約定を待つ、手数料低(≈0.02%)；テイカー(Taker, GTC)=積極的な約定、即時だが手数料高(≈0.05%)。",
    "help.maker_taker.note": "デフォルトではメイカーで注文を出して手数料を節約し（1取引あたり約0.03%）、価格が急に動いて待つと逃してしまうときだけテイカーで差を取りにいきます。",
    "help.isolation.concept": "メイングリッドの満建玉ラインとストップロスゾーンの開始点の間の緩衝距離。",
    "help.isolation.note": "メイングリッドが満建玉になった瞬間にストップロスが発動しないようにするためのものです。",
    "help.trailing_entry.concept": "すぐにグリッドを開始せず、まず価格の極値を監視し、一定割合の調整を待ってからポジションを建て、より有利なエントリーポイントを目指します。",
    "help.take_profit.concept": "グリッドの利益確定目標価格；価格がここに達してポジションが清算されると、ボックスは利益確定で終了します。",
    "help.main_grid.concept": "コア取引ゾーン — グリッド数×ステップが価格レンジとグリッド間隔を決定します。",
    "help.portion_size.concept": "各グリッド注文に置かれる基本数量（通貨ペアのベース資産単位、例: ETH）。",
    "help.leverage.concept": "契約レバレッジ倍率；ポジションと損益を拡大し、リスクも増加させます。",
    "help.stop_loss.concept": "価格が満建玉ラインを下回った後の清算保護 — グリッド数×ステップがストップロスゾーンの深さとペースを決定します。",
    "help.stop_loss.note": "最低ボックスは0グリッド設定可能＝ストップロスなし。",
    "help.activation.concept": "価格がこの点に達したときのみボックスが有効化されて取引を開始します；空白にするとメイングリッドの中間値が自動使用されます。",
    "help.mark_price.concept": "未実現損益と清算の計算に取引所が使用する参照価格（最終取引価格ではない）。",
    "help.position.concept": "現在保有しているコントラクト数量、方向（ロング/ショート）、平均取得価格。",
    "help.realized_pnl.concept": "決済済みポジションから確定した損益（手数料込み）。約定して決済された部分のみを集計し、現在価格に応じてリアルタイムには変動しません。",
    "help.realized_pnl.note": "このロボット/ボックスのすべての履歴セッションにわたって累積。",
    "help.unrealized_pnl.concept": "マーク価格でのオープンポジションの変動損益；決済まで価格とともに変動します。",
    "help.total_pnl.concept": "実現＋未実現の浮動損益 — 現在の総損益；未実現部分は市場とともにリアルタイムで変動します。",
    "help.total_pnl.note": "超過利益は既に実現損益に含まれており、追加されません。",
    "help.reorders.concept": "価格を追いかけてメイカーとして競争力を維持するために注文をキャンセルして再配置した回数。",
    "help.reorders.note": "現在のセッションでカウント。",
    "help.net_pnl.concept": "純損益 = 実現損益 − 手数料 − 資金調達料",
    "help.robot_total_pnl.concept": "ロボット総損益 = このロボットの全ボックスの純損益 + 現在ポジションの未実現損益",
