    "help.risk_tier.concept": "El nivel de riesgo lo deriva el sistema de forma determinista a partir del apalancamiento, el ancho de la caja frente a la volatilidad y si hay stop-loss (bajo/medio/alto), no solo de la autoevaluación del modelo.",
    "help.realized_volatility.concept": "Volatilidad realizada: fluctuación de precio anualizada calculada a partir de los rendimientos históricos; cuanto mayor, más bruscas son las oscilaciones.",
    "help.atr.concept": "ATR (rango medio verdadero): el movimiento medio por periodo, usado para evaluar si el paso de la rejilla se ajusta a la volatilidad del mercado.",
