    "notifications.POSITION_DRIFT_DETECTED": "{runCode} posición no coincide: DB={dbQty} exchange={exchangeQty}, verifique la sincronización de ejecuciones",
    "notifications.RECONCILE_REPEATED_FAILURE": "{symbol} {runCode} la reconciliación falló {count} veces seguidas, posible problema con la API del exchange",
    "help.fee.concept": "La comisión que cobra el exchange en cada ejecución; dividida en dos niveles — maker (límite/post-only) y taker (mercado).",
    "help.fee.note": "La comisión la cobra el exchange — GridPilot no se queda con nada. En la misma operación, maker ≈0.02% vs taker ≈0.05% (según tu exchange). Por defecto colocamos órdenes como maker para ahorrarte ~0.03% en cada una, y solo tomamos liquidez cuando una oportunidad fugaz se perdería de otro modo. Así que lo que ves aquí ya está optimizado para ti.",
    "help.fee.cta": "Comisiones y reembolsos",
    "help.savings.concept": "En esta ejecución, el diferencial extra ganado respecto al precio de grid nativo del exchange (precio medio del grid) — perseguimos activamente un mejor precio, algo que un grid nativo no puede hacer.",
    "help.avg_grid_price.concept": "Este es exactamente el precio de venta/compra que el propio bot de grid nativo del exchange publicaría en esta línea de grid. Cada una de nuestras ejecuciones reales lo supera — vendiendo más alto, comprando más bajo — y esa diferencia es el beneficio excedente (Alpha).",
    "help.fill_price.concept": "El precio al que realmente se ejecutó esta orden (precio de emparejamiento del exchange).",
    "help.order_price.concept": "El precio límite con el que publicamos originalmente esta orden; su diferencia con el precio de ejecución refleja la persecución de precio / deslizamiento.",
    "help.savings.note": "No es un cargo extra — es ganancia real del mecanismo de chase-order que te consigue una mejor ejecución, ya incluida en el P&L realizado; sumado todo, es tu beneficio excedente Alpha.",
    "help.alpha.concept": "Un grid nativo del exchange solo coloca órdenes estáticas a precios fijos; GridPilot persigue activamente una mejor ejecución y fija el diferencial en los grandes saltos de precio — esa ganancia extra es el beneficio excedente Alpha.",
    "help.alpha.note": "Esta es la ventaja de ejecución propia de GridPilot — un grid nativo del exchange no puede obtenerla. Ya está contabilizada en el P&L realizado, no se suma encima del P&L total.",
    "help.maker_taker.concept": "Maker (POC) = una orden límite pasiva esperando ser ejecutada, comisión baja (≈0.02%); taker (GTC) = una ejecución activa, instantánea pero con comisión mayor (≈0.05%).",
    "help.maker_taker.note": "Por defecto colocamos órdenes como maker para ahorrarte comisiones (~0.03% cada una); solo tomamos liquidez cuando el precio se aleja rápido y esperar significaría perder la oportunidad.",
    "help.isolation.concept": "La distancia de amortiguación entre la línea de posición completa del grid principal y el inicio de la zona de stop-loss.",
    "help.isolation.note": "Evita que el stop-loss se active en el momento en que el grid principal está completamente lleno.",
    "help.trailing_entry.concept": "En lugar de abrir el grid inmediatamente, monitorea el extremo de precio y espera una retroceso de un porcentaje establecido antes de entrar, buscando una mejor entrada.",
    "help.take_profit.concept": "El precio objetivo de beneficio del grid; cuando el precio llega y la posición se liquida, el box sale en beneficio.",
    "help.main_grid.concept": "La zona de trading principal — el número de grids × paso establece el rango de precio cubierto y el espaciado por grid.",
    "help.portion_size.concept": "La cantidad base colocada por orden de grid (en el activo base del par, p.ej. ETH).",
    "help.leverage.concept": "Multiplicador de apalancamiento del contrato; escala la posición y el P&L — y el riesgo.",
    "help.stop_loss.concept": "Protección de liquidación una vez que el precio supera la línea de posición completa — el número de grids × paso establece la profundidad y cadencia de la zona de stop-loss.",
    "help.stop_loss.note": "El box más bajo puede usar 0 grids = sin stop-loss.",
    "help.activation.concept": "El box solo se activa y comienza a operar cuando el precio alcanza este punto; déjalo en blanco para usar automáticamente el punto medio del grid principal.",
    "help.mark_price.concept": "El precio de referencia del exchange para calcular el P&L no realizado y la liquidación (no el último precio de trade).",
    "help.position.concept": "La cantidad actual del contrato, lado (largo/corto) y precio de entrada promedio.",
    "help.realized_pnl.concept": "Ganancia/pérdida bloqueada en posiciones cerradas (comisiones incluidas). Solo cuenta los cierres ya ejecutados y no varía en tiempo real con el precio actual.",
    "help.realized_pnl.note": "Acumulado en todas las sesiones históricas de este robot/box.",
    "help.unrealized_pnl.concept": "P&L flotante de la posición abierta al precio mark; fluctúa con el precio hasta que se cierra.",
    "help.total_pnl.concept": "Realizado + no realizado flotante — el P&L general actual; la parte no realizada varía en tiempo real con el mercado.",
    "help.total_pnl.note": "El beneficio excedente ya está incluido en el P&L realizado, no se suma encima.",
    "help.reorders.concept": "Cuántas veces se cancelaron y recolocaron órdenes para seguir el precio y mantenerse competitivo como maker.",
    "help.reorders.note": "Contado para la sesión actual.",
    "help.net_pnl.concept": "P&L neto = realizado − comisiones − financiación",
    "help.robot_total_pnl.concept": "P&L total del robot = P&L neto de todas las cajas del robot + no realizado de la posición actual",
    "referral.title": "Reduce tus comisiones: regístrate con un código de referido",
    "referral.subtitle": "Con apalancamiento y grids de alta frecuencia, las comisiones se acumulan sin que lo notes. Regístrate con un código de referido y recuperarás ~20% de las comisiones que pagues con el tiempo — como un descuento permanente en cada operación.",
    "referral.register_official": "Regístrate en el sitio oficial (código {code})",
