    "referral.empty_title": "Primero regístrate, luego conecta — no pierdas el reembolso permanente",
    "referral.empty_body": "Regístrate en OKX / Binance / Gate con un código de referido y obtén un reembolso automático y permanente del 20% en comisiones (40% en Gate). Solo puedes registrarte una vez por exchange y el reembolso solo se vincula al registrarte — las cuentas existentes no pueden añadirlo después. Esta es tu única oportunidad.",
