    "referral.cta_headline": "Agrega un código de reembolso al registrarte — 20% de comisiones de vuelta automáticamente (40% en Gate)",
    "referral.cta_sub": "Regístrate usando los botones a continuación (cada uno ya lleva el código de invitación correcto de su exchange); a partir de entonces, una parte de cada comisión vuelve automáticamente — un descuento permanente en cada operación. Las cuentas existentes no pueden añadirlo — el registro es la única oportunidad.",
