    "docs.nav": "Documentación de estrategia",
    "docs.title": "Documentación de la estrategia",
    "docs.subtitle": "El núcleo de GridPilot es la rejilla dinámica: comprar bajo y vender alto dentro de un rango predefinido, combinado con entrada con seguimiento, fijación de precios dinámica en tres zonas y amortiguadores escalonados de stop-loss, convirtiendo los mercados laterales en un flujo de caja constante cuantificado como Alpha.",
    "docs.lifecycle_label": "Ciclo de vida de la estrategia",
    "docs.life_entry_title": "Entrada con seguimiento",
    "docs.life_entry_desc": "Espera a que un retroceso se estabilice y confirme un rebote antes de entrar, evitando comprar en el techo",
    "docs.life_grid_title": "Rejilla en marcha",
    "docs.life_grid_desc": "Compra bajo y vende alto rejilla a rejilla; las órdenes POC se reciclan para acumular beneficio",
    "docs.life_tp_title": "Toma de beneficios",
    "docs.life_tp_desc": "Cierra en la línea de toma de beneficios o con posición completa; liquida P&L realizado y Alpha",
    "docs.zones_label": "Fijación de precios dinámica en tres zonas",
    "docs.zone_main": "Rejilla principal",
    "docs.zone_iso": "Amortiguador",
    "docs.zone_sl": "Zona de stop-loss",
    "docs.zone_main_title": "Rejilla principal · POC Maker",
    "docs.zone_main_desc": "La zona de negociación central. Todas las órdenes de la rejilla son Post-Only, solo Maker, comprando bajo y vendiendo alto rejilla a rejilla.",
    "docs.zone_iso_title": "Zona de amortiguación",
    "docs.zone_iso_desc": "Un amortiguador entre la rejilla principal y la zona de stop-loss, que evita activaciones erróneas repetidas en el límite.",
    "docs.zone_sl_title": "Zona de stop-loss · Reducción escalonada",
    "docs.zone_sl_desc": "Por debajo del inicio del stop-loss, la posición se reduce por niveles en lugar de toda de golpe, suavizando el deslizamiento y conservando el potencial alcista del rebote.",
    "docs.mech_label": "Mecanismos centrales",
    "docs.mech_boxes_title": "Cajas multisegmento",
    "docs.mech_boxes_desc": "Un robot puede mantener varios rangos de precio (cajas), absorbiendo distintos niveles por lotes para ampliar la cobertura y repartir el riesgo.",
    "docs.mech_entry_title": "Entrada con seguimiento",
    "docs.mech_entry_desc": "Antes de colocar órdenes, un retroceso con seguimiento identifica el mínimo; la primera orden se dispara solo cuando el rebote supera un umbral, reduciendo el coste de entrada.",
    "docs.mech_dynamic_title": "Órdenes dinámicas en tiempo real",
    "docs.mech_dynamic_desc": "Las órdenes se modifican continuamente a medida que el precio de marca se mueve, manteniéndolas alineadas con los precios objetivo de la rejilla y reduciendo fallos y desviaciones.",
    "docs.mech_sl_title": "Stop-loss por capas",
    "docs.mech_sl_desc": "La zona de stop-loss coloca órdenes algorítmicas por niveles, reduciendo gradualmente con un cierre total de emergencia como respaldo para controlar las caídas en movimientos extremos.",
    "docs.alpha_label": "Qué es Alpha",
    "docs.alpha_intro": "Alpha es el rendimiento excedente de GridPilot sobre una rejilla simple, compuesto por dos partes:",
    "docs.alpha_maker_term": "Ahorro Maker",
    "docs.alpha_maker_desc": "comisiones taker ahorradas por las órdenes POC",
    "docs.alpha_gtc_term": "Excedente GTC",
    "docs.alpha_gtc_desc": "beneficio extra captado en las rupturas",
    "docs.alpha_formula": "Alpha = Ahorro Maker + Excedente GTC",
    "docs.glossary_label": "Glosario",
    "docs.glossary_poc_term": "POC (Post-Only)",
    "docs.glossary_poc_desc": "Órdenes solo Maker que nunca toman; se vuelven a publicar si no se ejecutan.",
    "docs.glossary_gtc_term": "GTC (Good-Till-Cancel)",
    "docs.glossary_gtc_desc": "Órdenes de larga duración usadas para tomar activamente en las rupturas.",
    "docs.glossary_avg_term": "Precio medio de rejilla",
    "docs.glossary_avg_desc": "El precio objetivo teórico por rejilla, usado para calcular el ahorro.",
    "docs.glossary_full_term": "Línea de posición completa",
    "docs.glossary_full_desc": "El precio de posición máxima tras ejecutarse todas las compras de la rejilla.",
    "docs.risk_label": "Advertencia de riesgo",
    "docs.risk_body": "La negociación de futuros conlleva un alto riesgo por apalancamiento. Las estrategias de rejilla se adaptan a mercados laterales; una caída unidireccional puede activar el stop-loss o generar pérdidas. Dimensiona posiciones y apalancamiento con prudencia, e invierte solo lo que puedas permitirte perder.",
    "learn.fees.hero_title_accent": "devoren silenciosamente tu capital",
