    "ai.synth_conservative_rationale": "Une variante à effet de levier réduit, avec stop-loss et une boîte plus large, réduisant le risque de sortie de la boîte ou de liquidation.",
    "help.risk_tier.concept": "Le niveau de risque est dérivé de façon déterministe par le système à partir du levier, de la largeur de la boîte par rapport à la volatilité et de la présence d'un stop-loss (faible/moyen/élevé), pas seulement de l'auto-évaluation du modèle.",
    "help.realized_volatility.concept": "Volatilité réalisée : l'amplitude des variations de prix annualisée à partir des rendements passés ; plus elle est élevée, plus les mouvements sont forts.",
    "help.atr.concept": "ATR (Average True Range) : le mouvement moyen par période, utilisé pour juger si le pas de la grille correspond à la volatilité du marché.",
    "help.max_drawdown.concept": "Drawdown maximal : la plus forte baisse du sommet au creux sur la fenêtre, une mesure du risque baissier.",
