    "help.fee.concept": "Les frais que l'exchange prélève sur chaque exécution ; divisés en deux niveaux — maker (limite/post-only) et taker (marché).",
    "help.fee.note": "Les frais sont prélevés par l'exchange — GridPilot n'en prend rien. Pour une même opération, maker ≈0.02% contre taker ≈0.05% (selon votre exchange). Par défaut, nous plaçons des ordres maker pour vous faire économiser ~0.03% à chaque fois, et ne prenons de la liquidité que lorsqu'une opportunité fugace risquerait de vous échapper. Ce que vous voyez ici est donc déjà optimisé pour vous.",
    "help.fee.cta": "Frais et rétrocessions",
    "help.savings.concept": "Sur cette exécution, le différentiel supplémentaire gagné par rapport au prix de grid natif de l'exchange (prix moyen du grid) — nous poursuivons activement un meilleur prix, ce qu'un grid natif ne peut pas faire.",
    "help.avg_grid_price.concept": "C'est exactement le prix de vente/achat que le bot de grid natif de l'exchange afficherait sur cette ligne de grid. Chacune de nos exécutions réelles le dépasse — vendu plus haut, acheté plus bas — et cette différence est le bénéfice excédentaire (Alpha).",
    "help.fill_price.concept": "Le prix auquel cet ordre a réellement été exécuté (prix d'appariement de l'exchange).",
    "help.order_price.concept": "Le prix limite avec lequel nous avons initialement publié cet ordre ; son écart avec le prix d'exécution reflète la poursuite de prix / le slippage.",
    "help.savings.note": "Ce n'est pas un frais supplémentaire — c'est un gain réel du mécanisme d'ordre de poursuite qui vous obtient une meilleure exécution, déjà inclus dans le P&L réalisé ; cumulé, cela constitue votre bénéfice excédentaire Alpha.",
    "help.alpha.concept": "Un grid natif de la plateforme se contente de placer des ordres statiques à des prix fixes ; GridPilot poursuit activement une meilleure exécution et verrouille le différentiel lors des grands sauts de prix — ce gain supplémentaire est le bénéfice excédentaire Alpha.",
    "help.alpha.note": "C'est l'avantage d'exécution propre à GridPilot — un grid natif de la plateforme ne peut pas l'obtenir. Il est déjà comptabilisé dans le P&L réalisé, pas ajouté au-dessus du P&L total.",
    "help.maker_taker.concept": "Maker (POC) = un ordre limité passif attendant d'être exécuté, frais faibles (≈0.02%) ; taker (GTC) = une exécution active, instantanée mais avec des frais plus élevés (≈0.05%).",
    "help.maker_taker.note": "Par défaut, nous plaçons des ordres maker pour vous faire économiser des frais (~0.03% chacun) ; nous ne prenons de la liquidité que lorsque le prix s'envole et qu'attendre reviendrait à manquer l'occasion.",
    "help.isolation.concept": "La distance tampon entre la ligne de position complète du grid principal et le début de la zone de stop-loss.",
    "help.isolation.note": "Empêche le stop-loss de se déclencher au moment où le grid principal est entièrement rempli.",
    "help.trailing_entry.concept": "Au lieu d'ouvrir le grid immédiatement, il surveille l'extrême de prix et attend un recul d'un pourcentage défini avant d'entrer, visant un meilleur point d'entrée.",
    "help.take_profit.concept": "Le prix cible de profit du grid ; lorsque le prix l'atteint et que la position est liquidée, le box sort en bénéfice.",
    "help.main_grid.concept": "La zone de trading principale — le nombre de grids × le pas définit la plage de prix couverte et l'espacement par grid.",
    "help.portion_size.concept": "La quantité de base placée par ordre de grid (dans l'actif de base de la paire, par ex. ETH).",
    "help.leverage.concept": "Multiplicateur de levier du contrat ; il augmente la position et le P&L — et le risque.",
    "help.stop_loss.concept": "Protection de liquidation une fois que le prix dépasse la ligne de position complète — le nombre de grids × le pas définit la profondeur et la cadence de la zone de stop-loss.",
    "help.stop_loss.note": "Le box le plus bas peut utiliser 0 grids = pas de stop-loss.",
    "help.activation.concept": "Le box ne s'active et ne commence à trader que lorsque le prix atteint ce point ; laissez vide pour utiliser automatiquement le point médian du grid principal.",
    "help.mark_price.concept": "Le prix de référence de l'exchange pour calculer le P&L non réalisé et la liquidation (pas le dernier prix de trade).",
    "help.position.concept": "La quantité actuelle du contrat détenu, le côté (long/short) et le prix d'entrée moyen.",
    "help.realized_pnl.concept": "Profit/perte verrouillé depuis les positions fermées (frais inclus). Ne comptabilise que les clôtures déjà exécutées et ne varie pas en temps réel avec le prix actuel.",
    "help.realized_pnl.note": "Cumulé sur toutes les sessions historiques de ce robot/box.",
    "help.unrealized_pnl.concept": "P&L flottant de la position ouverte au prix mark ; il fluctue avec le prix jusqu'à la clôture.",
    "help.total_pnl.concept": "Réalisé + non réalisé flottant — le P&L global actuel ; la partie non réalisée varie en temps réel avec le marché.",
    "help.total_pnl.note": "Le profit excédentaire est déjà inclus dans le P&L réalisé, il n'est pas ajouté en plus.",
    "help.reorders.concept": "Combien de fois les ordres ont été annulés et repassés pour suivre le prix et rester compétitif en tant que maker.",
    "help.reorders.note": "Compté pour la session en cours.",
    "help.net_pnl.concept": "P&L net = réalisé − frais − financement",
    "help.robot_total_pnl.concept": "P&L total du robot = P&L net de toutes les boîtes du robot + non réalisé de la position actuelle",
    "referral.title": "Réduisez vos frais : inscrivez-vous avec un code de parrainage",
    "referral.subtitle": "Avec l'effet de levier et les grids à haute fréquence, les frais s'accumulent discrètement. Inscrivez-vous avec un code de parrainage et récupérez environ 20% des frais payés au fil du temps — comme une remise permanente sur chaque trade.",
