    "referral.empty_body": "Inscrivez-vous sur OKX / Binance / Gate avec un code de parrainage pour un remboursement automatique et permanent de 20% sur les frais (40% sur Gate). Vous ne pouvez vous inscrire qu'une seule fois par exchange et le remboursement ne se lie qu'à l'inscription — les comptes existants ne peuvent pas l'ajouter ensuite. C'est votre unique chance.",
