    "fees.title": "Frais et rebates",
    "fees.subtitle": "GridPilot ne facture aucune commission de stratégie — vous ne payez que les frais de l'exchange. La stratégie réduit activement le coût via un routage Maker-first et la capture d'excédent GTC, puis empile les rebates de l'exchange par-dessus, transformant chaque frais en Alpha quantifiable.",
