    "fees.lower_poc_desc": "Les ordres de grille sont Post-Only par défaut — Maker uniquement, jamais taker — pour des frais en attente plus bas, voire négatifs. C'est la principale source d'Alpha.",
    "fees.lower_gtc_title": "Capture d'excédent GTC",
    "fees.lower_gtc_desc": "Quand le prix s'envole rapidement, la stratégie prend dans la zone GTC pour compléter le cycle de la grille, verrouillant un profit excédentaire qui aurait été manqué — positif net même après les frais Taker.",
    "fees.lower_rebate_title": "Rebate de l'exchange",
