    "fees.table_note": "Les taux affichés sont des illustrations du palier de base ; les valeurs réelles dépendent du niveau VIP de chaque exchange et du type de contrat. Coût Maker net = taux Maker × (1 − ratio de rebate).",
    "fees.why_title": "Rebates de frais · transformez le coût en cash",
    "fees.why_p1": "Les stratégies de grille s'exécutent fréquemment, faisant des frais le plus gros coût caché. Les rebates reversent une part des frais déjà payés directement sur votre compte — sans changer aucun comportement de trading, tout en augmentant directement le rendement net. Plus vous exécutez, plus vous récupérez, en se cumulant avec l'Alpha de la stratégie.",
    "fees.why_p2": "Veillez à lier le code/lien d'invitation ci-dessous lors de l'inscription pour que le rebate prenne effet ; les comptes déjà enregistrés sans liaison ne peuvent pas le réclamer rétroactivement.",
