    "docs.nav": "Documentation de la stratégie",
    "docs.title": "Documentation de la stratégie",
    "docs.subtitle": "Le cœur de GridPilot est la grille dynamique : acheter bas et vendre haut dans une plage prédéfinie, complétée par une entrée suiveuse, une tarification dynamique à trois zones et des tampons de stop-loss par paliers, transformant les marchés latéraux en un flux de trésorerie régulier quantifié en Alpha.",
    "docs.lifecycle_label": "Cycle de vie de la stratégie",
    "docs.life_entry_title": "Entrée suiveuse",
    "docs.life_entry_desc": "Attendez qu'un repli se stabilise et confirme un rebond avant d'entrer, pour éviter d'acheter au sommet",
    "docs.life_grid_title": "Grille en marche",
    "docs.life_grid_desc": "Acheter bas, vendre haut grille par grille ; les ordres POC tournent pour accumuler du profit",
    "docs.life_tp_title": "Prise de profit",
    "docs.life_tp_desc": "Clôturer à la ligne de prise de profit ou à pleine position ; solder le P&L réalisé et l'Alpha",
