    "docs.zone_main_title": "Grille principale · POC Maker",
    "docs.zone_main_desc": "La zone de trading centrale. Tous les ordres de la grille sont Post-Only, Maker uniquement, achetant bas et vendant haut grille par grille.",
    "docs.zone_iso_title": "Zone tampon",
    "docs.zone_iso_desc": "Un tampon entre la grille principale et la zone de stop-loss, qui empêche les déclenchements erronés répétés à la frontière.",
    "docs.zone_sl_title": "Zone de stop-loss · Réduction par paliers",
    "docs.zone_sl_desc": "Sous le début du stop-loss, la position est réduite par paliers plutôt qu'en une seule fois, lissant le slippage et préservant le potentiel haussier du rebond.",
    "docs.mech_label": "Mécanismes essentiels",
    "docs.mech_boxes_title": "Boîtes multi-segments",
    "docs.mech_boxes_desc": "Un robot peut détenir plusieurs plages de prix (boîtes), absorbant différents niveaux par lots pour élargir la couverture et répartir le risque.",
    "docs.mech_entry_title": "Entrée suiveuse",
    "docs.mech_entry_desc": "Avant de placer des ordres, un repli suiveur identifie le plus bas ; le premier ordre ne se déclenche qu'une fois le rebond au-delà d'un seuil, réduisant le coût d'entrée.",
    "docs.mech_dynamic_title": "Ordres dynamiques en temps réel",
    "docs.mech_dynamic_desc": "Les ordres sont continuellement modifiés à mesure que le prix de marque évolue, restant alignés sur les prix cibles de la grille et réduisant les manqués et la dérive.",
    "docs.mech_sl_title": "Stop-loss par couches",
    "docs.mech_sl_desc": "La zone de stop-loss place des ordres algorithmiques par palier, réduisant progressivement avec une clôture totale d'urgence en repli pour maîtriser les pertes lors de mouvements extrêmes.",
    "docs.alpha_label": "Qu'est-ce que l'Alpha",
