    "docs.alpha_formula": "Alpha = Économie Maker + Excédent GTC",
    "docs.glossary_label": "Glossaire",
    "docs.glossary_poc_term": "POC (Post-Only)",
    "docs.glossary_poc_desc": "Ordres Maker uniquement qui ne prennent jamais ; republiés s'ils ne sont pas exécutés.",
    "docs.glossary_gtc_term": "GTC (Good-Till-Cancel)",
