    "docs.risk_label": "Avertissement sur les risques",
    "docs.risk_body": "Le trading de futures comporte un risque de levier élevé. Les stratégies de grille conviennent aux marchés latéraux ; une baisse unidirectionnelle peut déclencher le stop-loss ou des pertes. Dimensionnez les positions et le levier avec prudence, et n'investissez que ce que vous pouvez vous permettre de perdre.",
