    "ai.synth_conservative_rationale": "Uma variante com menor alavancagem, stop-loss e uma caixa mais ampla, reduzindo o risco de o preço sair da caixa ou atingir a liquidação.",
    "help.risk_tier.concept": "O nível de risco é derivado de forma determinística pelo sistema a partir da alavancagem, da largura da caixa em relação à volatilidade e da existência de stop-loss (baixo/médio/alto), não apenas da autoavaliação do modelo.",
    "help.realized_volatility.concept": "Volatilidade realizada: a flutuação de preço anualizada calculada a partir dos retornos históricos; quanto maior, mais bruscas as oscilações.",
    "help.atr.concept": "ATR (Average True Range): o movimento médio por período, usado para avaliar se o passo da grade corresponde à volatilidade do mercado.",
    "help.max_drawdown.concept": "Rebaixamento máximo: a maior queda do pico ao vale na janela, uma medida do risco de baixa.",
    "help.range_pct.concept": "Amplitude %: o intervalo percentual entre o preço mais alto e o mais baixo na janela.",
    "help.trend.concept": "Tendência: variação do preço em relação ao início da janela — positiva é de alta, negativa de baixa.",
    "help.vpvr_node.concept": "Nó de alto volume VPVR: um nível de preço com volume negociado concentrado, que costuma atuar como suporte/resistência.",
    "help.confidence.concept": "Confiança: a convicção subjetiva do modelo numa recomendação (0–100%), não uma taxa de acerto de backtest.",
