    "help.fee.note": "A taxa é cobrada pela exchange — a GridPilot não fica com nada. Na mesma operação, maker ≈0.02% vs taker ≈0.05% (conforme sua exchange). Por padrão, colocamos ordens como maker para te economizar ~0.03% em cada uma, e só consumimos liquidez quando uma oportunidade passageira seria perdida. Então o que você vê aqui já está otimizado para você.",
    "help.fee.cta": "Taxas e reembolsos",
    "help.savings.concept": "Nesta execução, o spread extra ganho em relação ao preço de grid nativo da corretora (preço médio do grid) — perseguimos ativamente um preço melhor, algo que um grid nativo não consegue fazer.",
    "help.avg_grid_price.concept": "Este é exatamente o preço de venda/compra que o próprio bot de grid nativo da corretora publicaria nesta linha de grid. Cada uma das nossas execuções reais supera esse preço — vendido mais alto, comprado mais baixo — e essa diferença é o lucro excedente (Alpha).",
    "help.fill_price.concept": "O preço pelo qual esta ordem foi realmente executada (preço de correspondência da corretora).",
    "help.order_price.concept": "O preço limite com o qual publicamos originalmente esta ordem; a diferença em relação ao preço de execução reflete a perseguição de preço / slippage.",
    "help.savings.note": "Não é uma cobrança extra — é ganho real do mecanismo de ordem de perseguição que consegue uma execução melhor para você, já incluído no P&L realizado; somado, é o seu lucro excedente Alpha.",
    "help.alpha.concept": "Um grid nativo da corretora apenas coloca ordens estáticas a preços fixos; o GridPilot persegue ativamente uma execução melhor e trava o spread nos grandes saltos de preço — esse ganho extra é o lucro excedente Alpha.",
    "help.alpha.note": "Esta é a vantagem de execução própria do GridPilot — um grid nativo da corretora não consegue obtê-la. Já está contabilizada no P&L realizado, não somada além do P&L total.",
    "help.maker_taker.concept": "Maker (POC) = uma ordem limite passiva aguardando ser executada, taxa baixa (≈0.02%); taker (GTC) = uma execução ativa, instantânea mas com taxa maior (≈0.05%).",
    "help.maker_taker.note": "Por padrão colocamos ordens como maker para economizar taxas (~0.03% cada); só consumimos liquidez quando o preço dispara e esperar significaria perder a oportunidade.",
    "help.isolation.concept": "A distância de amortecimento entre a linha de posição completa do grid principal e o início da zona de stop-loss.",
    "help.isolation.note": "Evita que o stop-loss seja acionado no momento em que o grid principal esteja completamente preenchido.",
    "help.trailing_entry.concept": "Em vez de abrir o grid imediatamente, monitora o extremo de preço e aguarda um recuo de percentual definido antes de entrar, buscando um ponto de entrada melhor.",
    "help.take_profit.concept": "O preço alvo de lucro do grid; quando o preço o atinge e a posição é encerrada, o box sai com lucro.",
    "help.main_grid.concept": "A zona de trading principal — o número de grids × passo define a faixa de preço coberta e o espaçamento por grid.",
    "help.portion_size.concept": "A quantidade base colocada por ordem de grid (no ativo base do par, ex. ETH).",
    "help.leverage.concept": "Multiplicador de alavancagem do contrato; aumenta a posição e o P&L — e o risco.",
    "help.stop_loss.concept": "Proteção de liquidação após o preço ultrapassar a linha de posição completa — o número de grids × passo define a profundidade e cadência da zona de stop-loss.",
    "help.stop_loss.note": "O box mais baixo pode usar 0 grids = sem stop-loss.",
    "help.activation.concept": "O box só ativa e começa a operar quando o preço atinge este ponto; deixe em branco para usar automaticamente o ponto médio do grid principal.",
    "help.mark_price.concept": "O preço de referência da exchange para calcular o P&L não realizado e liquidação (não o último preço de trade).",
    "help.position.concept": "A quantidade atual do contrato mantido, lado (long/short) e preço médio de entrada.",
    "help.realized_pnl.concept": "Lucro/perda travado em posições fechadas (taxas incluídas). Conta apenas os fechamentos já executados e não varia em tempo real com o preço atual.",
    "help.realized_pnl.note": "Acumulado em todas as sessões históricas deste robô/box.",
    "help.unrealized_pnl.concept": "P&L flutuante da posição aberta ao preço mark; flutua com o preço até ser fechada.",
    "help.total_pnl.concept": "Realizado + não realizado flutuante — o P&L geral atual; a parte não realizada varia em tempo real com o mercado.",
    "help.total_pnl.note": "O lucro excedente já está incluído no P&L realizado, não é adicionado por cima.",
    "help.reorders.concept": "Quantas vezes as ordens foram canceladas e recolocadas para perseguir o preço e manter-se competitivo como maker.",
    "help.reorders.note": "Contado para a sessão atual.",
    "help.net_pnl.concept": "P&L líquido = realizado − taxas − financiamento",
    "help.robot_total_pnl.concept": "P&L total do robô = P&L líquido de todas as caixas do robô + não realizado da posição atual",
