    "docs.nav": "Documentação da estratégia",
    "docs.title": "Documentação da estratégia",
    "docs.subtitle": "O núcleo do GridPilot é a grade dinâmica — comprar na baixa e vender na alta dentro de uma faixa predefinida, somada à entrada com seguimento, à precificação dinâmica em três zonas e a amortecedores escalonados de stop-loss, transformando mercados laterais em um fluxo de caixa estável quantificado como Alpha.",
