    "docs.zone_sl_title": "Zona de stop-loss · Redução escalonada",
    "docs.zone_sl_desc": "Abaixo do início do stop-loss, a posição é reduzida em etapas, em vez de tudo de uma vez, suavizando o deslizamento e mantendo o potencial de alta da recuperação.",
    "docs.mech_label": "Mecanismos centrais",
    "docs.mech_boxes_title": "Caixas multissegmento",
    "docs.mech_boxes_desc": "Um robô pode manter várias faixas de preço (caixas), absorvendo diferentes níveis em lotes para ampliar a cobertura e diluir o risco.",
    "docs.mech_entry_title": "Entrada com seguimento",
