    "help.fee.concept": "La commissione che l'exchange addebita su ogni esecuzione; suddivisa in due livelli — maker (limite/post-only) e taker (mercato).",
    "help.fee.note": "La commissione è addebitata dall'exchange — GridPilot non ne trattiene nulla. Nella stessa operazione, maker ≈0.02% contro taker ≈0.05% (secondo il tuo exchange). Per impostazione predefinita inseriamo ordini come maker per farti risparmiare ~0.03% ciascuno, e prendiamo liquidità solo quando un'occasione fugace andrebbe altrimenti persa. Quindi ciò che vedi qui è già ottimizzato per te.",
    "help.fee.cta": "Commissioni e rimborsi",
    "help.savings.concept": "Su questa esecuzione, lo spread aggiuntivo guadagnato rispetto al prezzo di grid nativo dell'exchange (prezzo medio del grid) — inseguiamo attivamente un prezzo migliore, qualcosa che un grid nativo non può fare.",
    "help.avg_grid_price.concept": "Questo è esattamente il prezzo di vendita/acquisto che il bot di grid nativo dell'exchange pubblicherebbe su questa linea di grid. Ognuna delle nostre esecuzioni reali lo supera — venduto più in alto, acquistato più in basso — e questa differenza è il profitto in eccesso (Alpha).",
    "help.fill_price.concept": "Il prezzo al quale questo ordine è stato effettivamente eseguito (prezzo di matching dell'exchange).",
    "help.order_price.concept": "Il prezzo limite con cui abbiamo originariamente pubblicato questo ordine; la sua differenza rispetto al prezzo di esecuzione riflette l'inseguimento del prezzo / lo slippage.",
    "help.savings.note": "Non è un addebito extra — è un guadagno reale dal meccanismo di ordine di inseguimento che ti ottiene un'esecuzione migliore, già incluso nel P&L realizzato; sommato, è il tuo profitto in eccesso Alpha.",
    "help.alpha.concept": "Un grid nativo dell'exchange si limita a piazzare ordini statici a prezzi fissi; GridPilot insegue attivamente un'esecuzione migliore e blocca lo spread nei grandi salti di prezzo — questo guadagno extra è il profitto in eccesso Alpha.",
    "help.alpha.note": "Questo è il vantaggio di esecuzione esclusivo di GridPilot — un grid nativo dell'exchange non può ottenerlo. È già conteggiato nel P&L realizzato, non aggiunto sopra al P&L totale.",
    "help.maker_taker.concept": "Maker (POC) = un ordine limite passivo in attesa di esecuzione, commissione bassa (≈0.02%); taker (GTC) = un'esecuzione attiva, immediata ma con commissione più alta (≈0.05%).",
    "help.maker_taker.note": "Per impostazione predefinita inseriamo ordini come maker per risparmiare commissioni (~0.03% ciascuno); prendiamo liquidità solo quando il prezzo scappa via e aspettare significherebbe perdere l'occasione.",
    "help.isolation.concept": "La distanza cuscinetto tra la linea di posizione piena del grid principale e l'inizio della zona di stop-loss.",
    "help.isolation.note": "Impedisce che lo stop-loss si attivi nel momento in cui il grid principale è completamente riempito.",
    "help.trailing_entry.concept": "Invece di aprire il grid immediatamente, monitora l'estremo di prezzo e attende un ritracciamento di una percentuale stabilita prima di entrare, puntando a un punto di ingresso migliore.",
    "help.take_profit.concept": "Il prezzo obiettivo di profitto del grid; quando il prezzo lo raggiunge e la posizione viene chiusa, il box esce in profitto.",
    "help.main_grid.concept": "La zona di trading principale — il numero di grid × passo definisce il range di prezzo coperto e la spaziatura per grid.",
    "help.portion_size.concept": "La quantità base posizionata per ogni ordine grid (nell'asset base della coppia, es. ETH).",
    "help.leverage.concept": "Moltiplicatore di leva del contratto; aumenta la posizione e il P&L — e il rischio.",
    "help.stop_loss.concept": "Protezione della liquidazione una volta che il prezzo supera la linea di posizione piena — il numero di grid × passo definisce la profondità e la cadenza della zona di stop-loss.",
    "help.stop_loss.note": "Il box più basso può usare 0 grid = nessuno stop-loss.",
    "help.activation.concept": "Il box si attiva e inizia a fare trading solo quando il prezzo raggiunge questo punto; lasciare vuoto per usare automaticamente il punto medio del grid principale.",
    "help.mark_price.concept": "Il prezzo di riferimento dell'exchange per calcolare il P&L non realizzato e la liquidazione (non l'ultimo prezzo di trade).",
    "help.position.concept": "La quantità attuale del contratto detenuto, il lato (long/short) e il prezzo di ingresso medio.",
    "help.realized_pnl.concept": "Profitto/perdita bloccato dalle posizioni chiuse (commissioni incluse). Conta solo le chiusure già eseguite e non varia in tempo reale con il prezzo attuale.",
    "help.realized_pnl.note": "Accumulato su tutte le sessioni storiche di questo robot/box.",
    "help.unrealized_pnl.concept": "P&L fluttuante della posizione aperta al prezzo mark; fluttua con il prezzo fino alla chiusura.",
    "help.total_pnl.concept": "Realizzato + non realizzato fluttuante — il P&L complessivo attuale; la parte non realizzata varia in tempo reale con il mercato.",
    "help.total_pnl.note": "Il profitto in eccesso è già incluso nel P&L realizzato, non viene aggiunto sopra.",
    "help.reorders.concept": "Quante volte gli ordini sono stati cancellati e ripiazzati per seguire il prezzo e rimanere competitivi come maker.",
    "help.reorders.note": "Contato per la sessione corrente.",
    "help.net_pnl.concept": "P&L netto = realizzato − commissioni − finanziamento",
    "help.robot_total_pnl.concept": "P&L totale del robot = P&L netto di tutte le box del robot + non realizzato della posizione corrente",
    "referral.title": "Riduci le tue commissioni: registrati con un codice referral",
    "referral.subtitle": "Con la leva e i grid ad alta frequenza, le commissioni si accumulano in silenzio. Registrati con un codice referral e recupererai circa il 20% delle commissioni pagate nel tempo — come uno sconto permanente su ogni operazione.",
    "referral.register_official": "Registrati sul sito ufficiale (codice {code})",
    "referral.invite_code": "Codice invito",
    "referral.mirror_hint": "Sito ufficiale non raggiungibile? (Cina continentale)",
    "referral.mirror_label": "Usa il dominio mirror di backup per la Cina continentale",
    "referral.disclaimer": "I mirror sono domini di backup di terze parti, da usare solo quando il sito ufficiale dell'exchange non è raggiungibile; verifica sempre che il codice invito corrisponda a quello mostrato sopra.",
    "referral.empty_title": "Prima registrati, poi connetti — non perdere il rimborso permanente",
    "referral.empty_body": "Registrati su OKX / Binance / Gate con un codice referral per un rimborso automatico e permanente del 20% sulle commissioni (40% su Gate). Puoi registrarti solo una volta per exchange e il rimborso si lega solo alla registrazione — i account esistenti non possono aggiungerlo in seguito. Questa è la tua unica occasione.",
    "referral.have_account_q": "Hai già un account su questo exchange?",
    "referral.have_account_no": "Non ancora",
    "referral.have_account_yes": "Sì, ce l'ho",
    "referral.oneshot_warning": "⚠️ Una sola registrazione per exchange; il rimborso si lega solo alla registrazione e non può essere aggiunto a un account esistente.",
    "referral.rebate_estimate": "Questo bot ha pagato ${fees} in commissioni — registrati su questo exchange con un codice invito per recuperare circa ${rebate} ({exchange} {rate}%).",
    "referral.rebate_cta_learn": "Registrati per rivendicare →",
    "referral.rebate_mute": "Uso già un codice referral — non mostrare più",
