    "referral.rebate_pnl_hint": "Registrati su questo exchange con un codice invito per recuperare circa ${rebate} di queste commissioni.",
    "referral.milestone": "Questo bot ha ora pagato ${fees} in commissioni — registrati su questo exchange con un codice invito per recuperare circa ${rebate}.",
    "referral.cta_headline": "Aggiungi un codice rimborso alla registrazione — il 20% delle commissioni torna automaticamente (40% su Gate)",
    "referral.cta_sub": "Registrati tramite i pulsanti sottostanti (ognuno porta già il codice invito corretto per il suo exchange); da quel momento una parte di ogni commissione torna automaticamente — uno sconto permanente su ogni operazione. I account esistenti non possono aggiungerlo — la registrazione è l'unica occasione.",
    "referral.register_btn": "Registrati su {name} · {rate}% di ritorno",
    "referral.tip_app": "Quando ti registri dall'app, inserisci il codice di invito manualmente — dimenticarlo significa niente rimborso.",
    "referral.tip_id": "Un documento, un account per exchange; già registrato — apri un altro con il documento di un familiare.",
    "learn.fees.nav": "Commissioni e finanziamento",
    "learn.fees.title": "Guida completa a commissioni e finanziamento",
    "learn.fees.page_intro": "Comprendere questi due costi è la base per la redditività a lungo termine del grid trading.",
    "learn.fees.hero_title": "Non lasciare che le commissioni erodano silenziosamente il tuo capitale",
    "learn.fees.bar_principal": "Il tuo capitale",
    "learn.fees.bar_taker": "Commissioni giornaliere · Taker 0.05%",
    "learn.fees.bar_maker": "Commissioni giornaliere · Maker 0.02%",
    "learn.fees.hero_takeaway": "Stessa strategia: passare da Taker a Maker risparmia 600 al giorno — ogni riduzione delle commissioni si accumula creando differenze di ordini di grandezza nel lungo termine.",
    "learn.fees.trading_fee_title": "Commissione di Trading",
    "learn.fees.maker_desc": "Ordini limite in attesa, eseguiti passivamente — forniscono liquidità, tariffa più bassa",
    "learn.fees.taker_desc": "Ordini di mercato / incrociati, eseguiti attivamente — consumano liquidità, tariffa più alta",
    "learn.fees.fee_note": "Addebitata dall'exchange — GridPilot non trattiene commissioni e usa l'esecuzione Maker per impostazione predefinita.",
    "learn.fees.funding_title": "Costo di finanziamento Funding Fee",
    "learn.fees.funding_cycle": "Liquidata ogni 8 ore (UTC)",
    "learn.fees.funding_dir": "Tasso positivo: i long pagano gli short; negativo: gli short pagano i long",
    "learn.fees.funding_note": "= nozionale della posizione × tasso; dipende solo dalle posizioni aperte — calcolalo come costo di mantenimento notturno.",
    "learn.fees.save_title": "Come ridurre le commissioni",
    "learn.fees.save_maker": "Maker prima · già l'impostazione predefinita di GridPilot",
    "learn.fees.save_rebate": "Rebate · registrati con un codice rebate per recuperare ~20% delle commissioni pagate",
    "fees.title": "Commissioni e rebate",
    "fees.subtitle": "GridPilot non addebita alcuna commissione di strategia — paghi solo le commissioni dell'exchange. La strategia riduce attivamente il costo con routing Maker-first e cattura dell'eccedenza GTC, poi vi somma i rebate dell'exchange, trasformando ogni commissione in Alpha quantificabile.",
    "fees.kpi_saved_label": "Commissioni risparmiate",
    "fees.kpi_saved_sub": "Risparmio Maker vs base all-taker",
    "fees.kpi_paid_label": "Commissioni pagate",
    "fees.kpi_paid_sub": "eseguite Maker-first",
    "fees.kpi_rebate_label": "Rebate stimato",
    "fees.kpi_rebate_sub": "maturato al tasso di rebate di ogni exchange",
    "fees.lower_title": "Come GridPilot riduce il tuo costo",
    "fees.lower_poc_title": "Routing POC Maker-first",
    "fees.lower_poc_desc": "Gli ordini di griglia sono Post-Only per impostazione predefinita — solo Maker, mai taker — per commissioni in attesa più basse o persino negative. Questa è la principale fonte di Alpha.",
    "fees.lower_gtc_title": "Cattura dell'eccedenza GTC",
    "fees.lower_gtc_desc": "Quando il prezzo scatta rapidamente, la strategia prende nella zona GTC per completare il ciclo della griglia, bloccando un profitto eccedente che altrimenti andrebbe perso — positivo netto anche dopo la commissione Taker.",
    "fees.lower_rebate_title": "Rebate dell'exchange",
    "fees.lower_rebate_desc": "Collega il tuo exchange con un codice invito dedicato e una parte delle commissioni pagate ti torna indietro — Binance / OKX 20%, Gate.io 40%.",
    "fees.table_title": "Tassi di commissione e rapporti di rebate",
    "fees.col_exchange": "Exchange",
    "fees.col_maker": "Tasso Maker",
    "fees.col_taker": "Tasso Taker",
    "fees.col_rebate": "Rebate",
    "fees.col_net": "Costo Maker netto",
    "fees.table_note": "I tassi mostrati sono illustrazioni del livello base; i valori reali dipendono dal livello VIP di ogni exchange e dal tipo di contratto. Costo Maker netto = tasso Maker × (1 − rapporto di rebate).",
    "fees.why_title": "Rebate sulle commissioni · trasforma il costo in contante",
    "fees.why_p1": "Le strategie di griglia eseguono frequentemente, rendendo le commissioni il maggiore costo nascosto. I rebate restituiscono una parte delle commissioni che hai già pagato direttamente sul tuo conto — senza cambiare alcun comportamento di trading, ma aumentando direttamente il rendimento netto. Più esegui, più recuperi, componendosi con l'Alpha della strategia.",
    "fees.why_p2": "Assicurati di collegare il codice/link invito qui sotto al momento della registrazione affinché il rebate abbia effetto; i conti già registrati senza collegamento non possono rivendicarlo retroattivamente.",
