    "fees.oneid_body": "Questa è la regola di controllo del rischio KYC di ogni exchange. Se hai già un conto su un exchange, di solito non può aggiungere un collegamento di rebate in seguito — puoi registrare un nuovo conto con il documento di un familiare e il codice invito sopra per godere del rebate. Assicurati del suo consenso e rispetta la legge locale e i termini dell'exchange.",
