    "docs.nav": "Documentazione strategia",
    "docs.title": "Documentazione della strategia",
    "docs.subtitle": "Il cuore di GridPilot è la griglia dinamica: comprare basso e vendere alto entro un intervallo predefinito, con in più ingresso a inseguimento, pricing dinamico a tre zone e buffer di stop-loss a livelli, trasformando i mercati laterali in un flusso di cassa costante quantificato come Alpha.",
    "docs.lifecycle_label": "Ciclo di vita della strategia",
    "docs.life_entry_title": "Ingresso a inseguimento",
    "docs.life_entry_desc": "Attendi che un ritracciamento si stabilizzi e confermi un rimbalzo prima di entrare, evitando di comprare sul massimo",
    "docs.life_grid_title": "Griglia in funzione",
    "docs.life_grid_desc": "Compra basso, vendi alto griglia per griglia; gli ordini POC ruotano per accumulare profitto",
    "docs.life_tp_title": "Presa di profitto",
    "docs.life_tp_desc": "Chiudi alla linea di presa di profitto o a posizione piena; liquida P&L realizzato e Alpha",
    "docs.zones_label": "Pricing dinamico a tre zone",
    "docs.zone_main": "Griglia principale",
