    "docs.zone_sl": "Zona di stop-loss",
    "docs.zone_main_title": "Griglia principale · POC Maker",
    "docs.zone_main_desc": "La zona di trading centrale. Tutti gli ordini della griglia sono Post-Only, solo Maker, comprando basso e vendendo alto griglia per griglia.",
    "docs.zone_iso_title": "Zona buffer",
    "docs.zone_iso_desc": "Un buffer tra la griglia principale e la zona di stop-loss, che previene attivazioni errate ripetute al confine.",
    "docs.zone_sl_title": "Zona di stop-loss · Riduzione a livelli",
    "docs.zone_sl_desc": "Sotto l'inizio dello stop-loss, la posizione viene ridotta a livelli anziché tutta in una volta, attenuando lo slippage e mantenendo il potenziale di rialzo del rimbalzo.",
    "docs.mech_label": "Meccanismi fondamentali",
    "docs.mech_boxes_title": "Box multi-segmento",
    "docs.mech_boxes_desc": "Un robot può gestire più intervalli di prezzo (box), assorbendo diversi livelli a lotti per ampliare la copertura e distribuire il rischio.",
    "docs.mech_entry_title": "Ingresso a inseguimento",
    "docs.mech_entry_desc": "Prima di piazzare gli ordini, un ritracciamento a inseguimento individua il minimo; il primo ordine scatta solo dopo che il rimbalzo supera una soglia, riducendo il costo d'ingresso.",
    "docs.mech_dynamic_title": "Ordini dinamici in tempo reale",
    "docs.mech_dynamic_desc": "Gli ordini vengono continuamente modificati al variare del prezzo mark, mantenendoli allineati ai prezzi obiettivo della griglia e riducendo mancati riempimenti e deriva.",
    "docs.mech_sl_title": "Stop-loss a strati",
    "docs.mech_sl_desc": "La zona di stop-loss piazza ordini algoritmici per livello, riducendo gradualmente con una chiusura totale d'emergenza come ripiego per controllare i drawdown in movimenti estremi.",
    "docs.alpha_label": "Cos'è Alpha",
    "docs.alpha_intro": "Alpha è il rendimento in eccesso di GridPilot rispetto a una griglia semplice, composto da due parti:",
    "docs.alpha_maker_term": "Risparmio Maker",
    "docs.alpha_maker_desc": "commissioni taker risparmiate dagli ordini POC",
