    "docs.alpha_gtc_desc": "profitto extra catturato nei breakout",
    "docs.alpha_formula": "Alpha = Risparmio Maker + Eccedenza GTC",
    "docs.glossary_label": "Glossario",
    "docs.glossary_poc_term": "POC (Post-Only)",
    "docs.glossary_poc_desc": "Ordini solo Maker che non prendono mai; ripubblicati se non eseguiti.",
    "docs.glossary_gtc_term": "GTC (Good-Till-Cancel)",
