    "docs.glossary_full_term": "Linea di posizione piena",
    "docs.glossary_full_desc": "Il prezzo di posizione massima dopo l'esecuzione di tutti gli acquisti della griglia.",
    "docs.risk_label": "Avviso di rischio",
    "docs.risk_body": "Il trading di futures comporta un elevato rischio di leva. Le strategie a griglia sono adatte ai mercati laterali; un calo unidirezionale può attivare lo stop-loss o generare perdite. Dimensiona posizioni e leva con prudenza e investi solo ciò che puoi permetterti di perdere.",
