    "notifications.RECONCILE_REPEATED_FAILURE": "{symbol} {runCode} 대사가 {count}회 연속 실패, 거래소 API 문제일 수 있습니다",
    "help.fee.concept": "거래소가 각 체결에 대해 부과하는 수수료; 메이커(Maker)와 테이커(Taker) 두 등급으로 나뉩니다.",
    "help.fee.note": "수수료는 거래소가 부과하며 GridPilot은 한 푼도 가져가지 않습니다. 같은 거래라도 메이커(Maker)는 약 0.02%, 테이커(Taker)는 약 0.05%(거래소마다 다름)입니다 — 저희는 기본적으로 메이커로 주문을 넣어 거래당 약 0.03%를 절약해 드리고, 놓치면 아까운 찰나의 기회일 때만 테이커를 사용합니다. 그래서 여기 보이는 값은 이미 당신을 위해 최적화된 결과입니다.",
    "help.fee.cta": "수수료 및 리베이트",
    "help.savings.concept": "이번 체결에서 거래소 네이티브 그리드 주문가(평균 그리드 가격) 대비 추가로 얻은 가격차 — 더 유리한 가격을 능동적으로 추격해서 얻은 것으로, 네이티브 그리드로는 할 수 없는 일입니다.",
    "help.avg_grid_price.concept": "이것은 거래소의 네이티브 그리드 봇이 이 그리드 라인에서 게시했을 매도가/매수가 그 자체입니다. 저희의 모든 실제 체결은 이를 능가합니다 — 더 높게 매도하고 더 낮게 매수하며, 그 차액이 초과 수익(Alpha)입니다.",
    "help.fill_price.concept": "이 주문이 실제로 체결된 가격(거래소 매칭 가격)입니다.",
    "help.order_price.concept": "이 주문을 처음 게시했을 때의 주문가입니다; 체결가와의 차이는 가격 추격/슬리피지를 반영합니다.",
    "help.savings.note": "추가 수수료가 아니라 — 추격 주문 메커니즘이 더 유리한 체결을 달성하여 얻은 실제 수익이며, 이미 실현 손익에 포함되어 있습니다; 누적하면 Alpha 초과 수익이 됩니다.",
    "help.alpha.concept": "거래소 기본 그리드는 고정 가격에 주문을 걸어 수동적으로 체결을 기다릴 뿐입니다. GridPilot은 더 유리한 체결을 능동적으로 추격하고 큰 가격 변동 시 가격차를 확정합니다 — 이렇게 더 벌어들인 부분이 Alpha 초과 수익입니다.",
    "help.alpha.note": "이것은 GridPilot 고유의 실행 능력으로, 거래소 기본 그리드로는 얻을 수 없습니다. 이미 「실현 손익」에 반영되어 있으며, 총 손익에 추가로 더해지지 않습니다.",
    "help.maker_taker.concept": "메이커(Maker, POC) = 수동적인 지정가 주문으로 체결 대기, 낮은 수수료(≈0.02%); 테이커(Taker, GTC) = 능동적 체결, 즉각적이지만 높은 수수료(≈0.05%).",
    "help.maker_taker.note": "기본적으로 메이커로 주문을 넣어 수수료를 아껴 드리고(거래당 약 0.03%), 가격이 빠르게 벌어져 기다리면 놓칠 때만 테이커로 차익을 잡습니다.",
    "help.isolation.concept": "메인 그리드의 최대 포지션 라인과 스톱로스 구역 시작점 사이의 완충 거리.",
    "help.isolation.note": "메인 그리드가 완전히 채워지는 순간 스톱로스가 발동하는 것을 방지합니다.",
    "help.trailing_entry.concept": "그리드를 즉시 열지 않고 가격 극값을 추적하다가 설정된 비율만큼 되돌림이 발생한 후 포지션을 진입하여 더 유리한 진입점을 목표로 합니다.",
    "help.take_profit.concept": "그리드의 목표 수익 가격; 가격이 이에 도달하고 포지션이 청산되면 박스가 수익으로 종료됩니다.",
    "help.main_grid.concept": "핵심 거래 구역 — 그리드 수 × 스텝이 커버되는 가격 범위와 그리드 간격을 결정합니다.",
    "help.portion_size.concept": "그리드 주문당 배치되는 기본 수량 (쌍의 기본 자산 단위, 예: ETH).",
    "help.leverage.concept": "계약 레버리지 배수; 포지션과 손익을 확대하고 — 위험도 증가시킵니다.",
    "help.stop_loss.concept": "가격이 최대 포지션 라인을 돌파한 후의 청산 보호 — 그리드 수 × 스텝이 스톱로스 구역의 깊이와 템포를 결정합니다.",
    "help.stop_loss.note": "최하위 박스는 0 그리드 설정 가능 = 스톱로스 없음.",
    "help.activation.concept": "가격이 이 지점에 도달할 때만 박스가 활성화되어 거래를 시작합니다; 비워두면 메인 그리드의 중간값을 자동으로 사용합니다.",
    "help.mark_price.concept": "미실현 손익과 청산 계산에 거래소가 사용하는 기준 가격 (마지막 거래 가격이 아님).",
    "help.position.concept": "현재 보유 중인 계약 수량, 방향 (롱/숏), 평균 진입 가격.",
    "help.realized_pnl.concept": "청산된 포지션에서 확정된 이익/손실(수수료 포함)입니다. 이미 체결되어 청산된 부분만 집계하며 현재 가격에 따라 실시간으로 변동하지 않습니다.",
    "help.realized_pnl.note": "이 로봇/박스의 모든 이력 세션에 걸쳐 누적.",
    "help.unrealized_pnl.concept": "마크 가격 기준 열린 포지션의 변동 손익; 청산될 때까지 가격에 따라 변동합니다.",
    "help.total_pnl.concept": "실현 + 미실현 변동 손익 — 현재 전체 손익입니다; 미실현 부분은 시장에 따라 실시간으로 변동합니다.",
    "help.total_pnl.note": "초과 이익은 이미 실현 손익에 포함되어 있으며, 추가로 더해지지 않습니다.",
    "help.net_pnl.concept": "순 손익 = 실현 − 수수료 − 펀딩",
    "help.robot_total_pnl.concept": "로봇 총 손익 = 로봇의 모든 박스 순 손익 + 현재 포지션 미실현 손익",
    "help.reorders.concept": "가격을 추적하고 메이커로서 경쟁력을 유지하기 위해 주문을 취소하고 재배치한 횟수.",
    "help.reorders.note": "현재 세션 기준으로 집계.",
