    "fees.lower_poc_desc": "그리드 주문은 기본적으로 Post-Only — Maker 전용으로 결코 taker가 되지 않아 대기 수수료를 더 낮게, 때로는 마이너스로 만듭니다. 이것이 Alpha의 주요 원천입니다.",
