    "fees.table_note": "표시된 요율은 기본 등급 예시이며, 실제 값은 각 거래소의 VIP 레벨과 계약 유형에 따라 다릅니다. Maker 순비용 = Maker 율 × (1 − 리베이트 비율).",
    "fees.why_title": "수수료 리베이트 · 비용을 현금으로 되돌리기",
    "fees.why_p1": "그리드 전략은 체결이 빈번해 수수료가 가장 큰 숨은 비용이 됩니다. 리베이트는 이미 지급한 수수료의 일부를 그대로 계좌로 돌려줍니다 — 어떤 거래 행동도 바꾸지 않으면서 순수익을 직접 끌어올립니다. 많이 체결할수록 더 많이 돌려받아 전략의 Alpha와 복리로 작용합니다.",
