    "docs.subtitle": "GridPilot의 핵심은 동적 그리드입니다. 미리 설정한 범위 안에서 저점 매수·고점 매도를 하고, 여기에 추적 진입, 3구간 동적 가격 책정, 단계별 손절 버퍼를 더해 횡보장을 안정적인 현금 흐름으로 바꾸어 Alpha로 정량화합니다.",
