    "docs.zone_sl_title": "손절 구간 · 단계적 감축",
    "docs.zone_sl_desc": "손절 시작선 아래에서는 한 번에 전부가 아니라 단계적으로 포지션을 줄여 슬리피지를 완화하고 반등 상승 여력을 남깁니다.",
    "docs.mech_label": "핵심 메커니즘",
    "docs.mech_boxes_title": "다중 구간 박스",
    "docs.mech_boxes_desc": "로봇 하나가 여러 가격 범위(박스)를 보유할 수 있어, 서로 다른 구간을 분할로 흡수하여 커버리지를 넓히고 리스크를 분산합니다.",
    "docs.mech_entry_title": "추적 진입",
    "docs.mech_entry_desc": "주문을 내기 전에 추적 되돌림으로 저점을 식별하며, 반등이 임계값을 넘은 뒤에야 첫 주문이 발동되어 진입 비용을 낮춥니다.",
    "docs.mech_dynamic_title": "실시간 동적 주문",
    "docs.mech_dynamic_desc": "마크 가격이 움직이는 동안 주문을 계속 수정하여 그리드 목표 가격에 맞추고, 미체결과 이탈을 줄입니다.",
