    "docs.risk_label": "리스크 경고",
    "docs.risk_body": "선물 거래에는 높은 레버리지 리스크가 따릅니다. 그리드 전략은 횡보장에 적합하며, 일방적인 하락은 손절이나 손실을 유발할 수 있습니다. 포지션과 레버리지를 신중하게 설정하고, 잃어도 감당할 수 있는 자금만 투자하세요.",
