    "notifications.RUNNER_RESIDUAL_POSITION": "Thanh lý {symbol} chưa hoàn tất, vẫn còn vị thế tồn dư; vui lòng kiểm tra và đóng thủ công: {reason}",
    "notifications.RUNNER_ORDER_REJECTED": "{symbol} lệnh bị từ chối: {reason}",
