    "notifications.RECONCILE_REPEATED_FAILURE": "{symbol} {runCode} đối soát thất bại {count} lần liên tiếp, có thể do sự cố API của sàn",
    "help.fee.concept": "Phí mà sàn giao dịch thu trên mỗi lệnh khớp; chia thành hai mức — maker (lệnh giới hạn/post-only) và taker (lệnh thị trường).",
    "help.fee.note": "Phí do sàn giao dịch thu — GridPilot không lấy một phần nào. Trong cùng một giao dịch, maker ≈0.02% so với taker ≈0.05% (tùy sàn của bạn). Mặc định chúng tôi đặt lệnh maker để giúp bạn tiết kiệm ~0.03% mỗi lần, và chỉ lấy thanh khoản khi một cơ hội thoáng qua sắp vuột mất. Vì vậy những gì bạn thấy ở đây đã được tối ưu cho bạn.",
    "help.fee.cta": "Phí và hoàn phí",
    "help.savings.concept": "Ở lệnh khớp này, phần chênh lệch giá tăng thêm có được so với giá lưới gốc của sàn (giá lưới trung bình) — chúng tôi chủ động đuổi theo mức giá tốt hơn, điều mà lưới gốc không làm được.",
    "help.avg_grid_price.concept": "Đây chính là mức giá bán/mua mà bot lưới gốc của sàn sẽ đặt trên đường lưới này. Mỗi lệnh khớp thực tế của chúng tôi đều vượt qua mức đó — bán cao hơn, mua thấp hơn — và phần chênh lệch đó là lợi nhuận vượt trội (Alpha).",
    "help.fill_price.concept": "Mức giá mà lệnh này thực sự được khớp (giá khớp của sàn).",
    "help.order_price.concept": "Giá đặt lệnh ban đầu của lệnh này; khoảng cách so với giá khớp phản ánh việc đuổi giá / trượt giá.",
    "help.savings.note": "Đây không phải là khoản phí thêm — đây là lợi nhuận thực từ cơ chế lệnh đuổi giúp bạn khớp lệnh tốt hơn, đã được tính trong lợi nhuận/thua lỗ đã thực hiện; cộng dồn lại chính là lợi nhuận vượt trội Alpha.",
    "help.alpha.concept": "Lưới gốc của sàn chỉ đặt lệnh tĩnh ở mức giá cố định và thụ động chờ khớp; GridPilot chủ động đuổi theo mức giá khớp tốt hơn và chốt chênh lệch khi giá biến động mạnh — phần lợi nhuận tăng thêm đó chính là lợi nhuận vượt trội Alpha.",
    "help.alpha.note": "Đây là năng lực thực thi riêng có của GridPilot — lưới gốc của sàn không thể đạt được. Nó đã được tính trong lợi nhuận/thua lỗ đã thực hiện, không cộng thêm vào tổng lợi nhuận/thua lỗ.",
    "help.maker_taker.concept": "Maker (POC) = lệnh giới hạn thụ động chờ khớp, phí thấp (≈0.02%); taker (GTC) = khớp lệnh chủ động, tức thời nhưng phí cao hơn (≈0.05%).",
    "help.maker_taker.note": "Mặc định chúng tôi đặt lệnh maker để giúp bạn tiết kiệm phí (~0.03% mỗi lần); chỉ lấy thanh khoản khi giá chạy nhanh và chờ thêm sẽ bỏ lỡ cơ hội.",
    "help.isolation.concept": "Khoảng cách đệm giữa đường vị thế đầy của lưới chính và điểm bắt đầu của vùng cắt lỗ.",
    "help.isolation.note": "Ngăn cắt lỗ kích hoạt ngay khi lưới chính được lấp đầy hoàn toàn.",
    "help.trailing_entry.concept": "Thay vì mở lưới ngay lập tức, theo dõi mức giá cực trị và chờ giá kéo ngược một tỷ lệ xác định trước khi vào lệnh, nhằm đạt điểm vào tốt hơn.",
    "help.take_profit.concept": "Giá mục tiêu lợi nhuận của lưới; khi giá đạt đến và vị thế được đóng, box thoát với lợi nhuận.",
    "help.main_grid.concept": "Vùng giao dịch cốt lõi — số lưới × bước xác định phạm vi giá bao phủ và khoảng cách mỗi lưới.",
    "help.portion_size.concept": "Số lượng cơ bản đặt cho mỗi lệnh lưới (tính theo tài sản cơ sở của cặp, ví dụ ETH).",
    "help.leverage.concept": "Hệ số đòn bẩy hợp đồng; khuếch đại vị thế và lợi nhuận/thua lỗ — và cả rủi ro.",
    "help.stop_loss.concept": "Bảo vệ thanh lý khi giá phá vỡ đường vị thế đầy — số lưới × bước xác định độ sâu và nhịp điệu của vùng cắt lỗ.",
    "help.stop_loss.note": "Box thấp nhất có thể dùng 0 lưới = không có cắt lỗ.",
    "help.activation.concept": "Box chỉ kích hoạt và bắt đầu giao dịch khi giá đạt điểm này; để trống để tự dùng điểm giữa của lưới chính.",
    "help.mark_price.concept": "Giá tham chiếu của sàn giao dịch để tính lợi nhuận/thua lỗ chưa thực hiện và thanh lý (không phải giá giao dịch cuối cùng).",
    "help.position.concept": "Số lượng hợp đồng đang nắm giữ, chiều (long/short) và giá vào trung bình.",
    "help.realized_pnl.concept": "Lợi nhuận/thua lỗ đã khóa từ các vị thế đã đóng (bao gồm phí). Chỉ tính phần đã khớp và đóng, không thay đổi theo thời gian thực theo giá hiện tại.",
    "help.realized_pnl.note": "Tích lũy qua tất cả phiên lịch sử của robot/box này.",
    "help.unrealized_pnl.concept": "Lợi nhuận/thua lỗ nổi của vị thế mở tại giá mark; biến động theo giá cho đến khi đóng.",
    "help.total_pnl.concept": "Đã thực hiện + lợi nhuận thả nổi chưa thực hiện — tổng lợi nhuận/thua lỗ hiện tại; phần chưa thực hiện thay đổi theo thời gian thực theo thị trường.",
    "help.total_pnl.note": "Lợi nhuận vượt trội đã được tính trong lợi nhuận/thua lỗ đã thực hiện, không cộng thêm.",
    "help.net_pnl.concept": "Lãi/lỗ ròng = đã thực hiện − phí − phí tài trợ",
    "help.robot_total_pnl.concept": "Tổng lãi/lỗ robot = lãi/lỗ ròng của tất cả các hộp của robot + chưa thực hiện của vị thế hiện tại",
    "help.reorders.concept": "Số lần lệnh bị hủy và đặt lại để đuổi theo giá và duy trì tính cạnh tranh với tư cách maker.",
    "help.reorders.note": "Đếm cho phiên hiện tại.",
